import React, { useState, useEffect } from "react";
import "./Navbar.css";
import { FiSearch, FiShoppingCart } from "react-icons/fi";
import LocationMap from "./LocationMap";

const Navbar = ({
  cartCount,
  cartTotal,
  openCart,
  isLoggedIn,
  setIsLoggedIn,
  showLoginModal,
  setShowLoginModal,
  setShowCart,
  cart,
  deliveryDisplay = "8 minutes",
  onLocationUpdate,
  getDeliveryInfoForCoords,
  deliveryAvailable,
  storeLat,
  storeLng,
  onLogoClick,
}) => {
  const [open, setOpen] = useState(false);
  const [phone, setPhone] = useState("");
  const [loginSuccess, setLoginSuccess] = useState(false);
  const [showAccountDropdown, setShowAccountDropdown] = useState(false);
  const [detectingLocation, setDetectingLocation] = useState(false);
  const [locationError, setLocationError] = useState(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [searchingLocation, setSearchingLocation] = useState(false);
  const [searchError, setSearchError] = useState(null);
  const [pendingLocation, setPendingLocation] = useState(null);

  const suggestions = [
    "curd",
    "chocolate",
    "chips",
    "milk",
    "rice",
    "egg",
    "bread",
    "sugar",
    "butter",
  ];

  const [index, setIndex] = useState(0);
  const [searchValue, setSearchValue] = useState("");

  /* ---------------- SEARCH ANIMATION ---------------- */
  useEffect(() => {
    if (searchValue !== "") return;

    const interval = setInterval(() => {
      setIndex((prev) => (prev + 1) % suggestions.length);
    }, 2000);

    return () => clearInterval(interval);
  }, [searchValue]);

  /* ---------------- CHECK LOGIN ---------------- */
  useEffect(() => {
    const saved = localStorage.getItem("blinkitUser");
    if (saved) {
      setIsLoggedIn(true);
      setPhone(saved);
    }
  }, [setIsLoggedIn]);

  const handleLogin = () => {
    if (phone.length !== 10) return;

    localStorage.setItem("blinkitUser", phone);
    setIsLoggedIn(true);
    setLoginSuccess(true);

    setTimeout(() => {
      setShowLoginModal(false);
      setLoginSuccess(false);
    }, 1200);
  };

  const handleLogout = () => {
    localStorage.removeItem("blinkitUser");
    setIsLoggedIn(false);
    setShowAccountDropdown(false);
  };
  console.log("Login Setter:", setShowLoginModal);

  /* ---------------- CART COUNT ---------------- */
  const totalItems = Object.values(cart || {}).reduce(
    (sum, qty) => sum + qty,
    0,
  );

  /* ---------------- SEARCH LOCATION (GEOCODE) ---------------- */
  const handleSearchLocation = async () => {
    const query = searchQuery.trim();
    if (!query) return;
    setSearchError(null);
    setSearchingLocation(true);
    try {
      const res = await fetch(
        `https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(query)}&format=json&limit=1`,
        {
          headers: {
            "Accept-Language": "en",
            "User-Agent": "BlinkitClone/1.0",
          },
        },
      );
      const data = await res.json();
      if (!Array.isArray(data) || data.length === 0) {
        setSearchError("Location not found. Try a different city or area.");
        return;
      }
      const first = data[0];
      const lat = parseFloat(first.lat);
      const lng = parseFloat(first.lon);
      const address = first.display_name || query;
      setPendingLocation({ lat, lng, address });
    } catch (_) {
      setSearchError("Could not search location. Please try again.");
    } finally {
      setSearchingLocation(false);
    }
  };

  return (
    <>
