import "./ProductCard.css";

const ProductCard = ({
  product,
  cart,
  setCart,
  isLoggedIn = false,
  openLoginModal,
  deliveryDisplay,
  setSelectedProductId,
}) => {
  const count = cart[product.id] || 0;
  const deliveryText = deliveryDisplay
    ? `${(deliveryDisplay.replace(/\D/g, "") || "8").trim() || "8"} MINS`
    : product.delivery;

  const addItem = (e) => {
    e.stopPropagation();
    setCart((prev) => ({
      ...prev,
      [product.id]: (prev[product.id] || 0) + 1,
    }));
  };

  const increase = (e) => {
    e.stopPropagation();
    setCart((prev) => ({
      ...prev,
      [product.id]: (prev[product.id] || 0) + 1,
    }));
  };

  const decrease = (e) => {
    e.stopPropagation();
    setCart((prev) => {
      const current = prev[product.id] || 0;
      const newCount = current - 1;

      if (newCount <= 0) {
        const updated = { ...prev };
        delete updated[product.id];
        return updated;
      }

      return {
        ...prev,
        [product.id]: newCount,
      };
    });
  };

  return (
    <div
      className="product-card"
      onClick={() => setSelectedProductId && setSelectedProductId(product.id)}
    >
      <div className="top-section">
        <img src={product.image} alt={product.title} loading="lazy" />

        <div className="delivery">ΓÅ▒ {deliveryText}</div>

        <h4>{product.title}</h4>
        <p>{product.quantity}</p>
      </div>

      <div className="bottom">
        <span className="price">Γé╣{product.price}</span>

        {count === 0 ? (
          <button
            className={`add-btn ${!isLoggedIn ? "disabled-btn" : ""}`}
            onClick={addItem}
          >
            ADD
          </button>
        ) : (
          <div className="counter">
            <button onClick={decrease}>-</button>
            <span>{count}</span>
            <button onClick={increase}>+</button>
          </div>
        )}
      </div>
    </div>
  );
};

